  display:block;width:100%;aspect-ratio:4 / 3;object-fit:cover;
  border-radius:var(--aha-radius-xl);background:var(--aha-bg-container-secondary);
}
.aha-header-section-hero-pink--vertical .aha-header-section-hero-pink__inner{flex-direction:column;justify-content:flex-start;gap:var(--aha-space-48)}
.aha-header-section-hero-pink--vertical .aha-header-section-hero-pink__copy{align-items:center;text-align:center}
.aha-header-section-hero-pink--vertical .aha-header-section-hero-pink__media{max-width:960px}
.aha-header-section-hero-pink--vertical .aha-header-section-hero-pink__image{aspect-ratio:16 / 9}
