  .aha-header-section-hero-pink__title{font-size:var(--aha-size-h4)}
}
.aha-header-section-hero-pink__splash{display:none}
.aha-header-section-hero-pink:not(.aha-header-section-hero-pink--pale) .aha-header-section-hero-pink__splash{display:block;position:absolute;inset:0;z-index:0;overflow:hidden;container-type:size;pointer-events:none;border-radius:inherit;--aha-header-section-hero-pink-splash-width:calc(4.5*min(100cqw,100cqh)*sqrt(max(1,tan(atan2(100cqw,100cqh))*9/16,9/16/tan(atan2(100cqw,100cqh)))))}
.aha-header-section-hero-pink__splash-icon{position:absolute;display:block;max-width:none;height:auto;width:var(--aha-header-section-hero-pink-splash-width);left:calc(var(--aha-header-section-hero-pink-splash-across)*100cqw - var(--aha-header-section-hero-pink-splash-width)*0.516209);top:calc(55cqh - var(--aha-header-section-hero-pink-splash-width)*0.418953)}
.aha-header-section-hero-pink__splash{--aha-header-section-hero-pink-splash-across:.75}

